answer:
function escapeHtml(s) {
  return s
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function commentHtml(name, body) {
  return `<li><strong>${escapeHtml(name)}</strong> ${escapeHtml(body)}</li>`;
}

console.log(commentHtml("さば", "こんにちは"));

